UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><p>Be part of a rapidly evolving industry with extraordinary opportunities. Artificial Intelligence systems are playing a key role in the modern world, meaning professionals with high level IT and Data Science qualifications are in high demand.</p><p>The Bachelor of Information Technology (Artificial Intelligence and Data Science) gives you a broad knowledge applicable to the IT industry in both well-established technologies and emerging IT trends. In your first year of study you’ll obtain the required core IT foundations, and then become ‘job-ready’ by completing specialist AI and Data Science units, plus our mandatory career development units including 60 days of paid placement through Federation Co-op.</p></div><div><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Information Technology</p><h4>Course co-ordinator</h4><p>Bhavna Antony</p></div></div>',
    total_course_duration = '3 years full-time or part-time equivalent360 credit points = 3.0',
    offshore_tuition_fee = '41400',
    entry_requirements = '<section class="accordionContainerBlock py-12 lg:py-16 !pt-6 lg:!pt-12 !pb-4 lg:!pb-8" data-blk="AccordionContainerBlock" id="entry-requirement"><div class="container mx-auto"><p class="fs-5xl mb-8 font-semibold text-primary" style="font-weight:bold;"><p data-pm-slice="1 1 []">Entry requirements</p></p><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:ra:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:rb:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 420px;"><div class="prose px-4 pb-8"><h4>Academic entry requirements</h4><p>Successful completion of Australian Year 12, or overseas equivalent.</p><h4>English language requirements</h4><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent</p><h4><abbr title="Australian Tertiary Admission Rank">ATAR</abbr></h4><p></p><p>Guaranteed ATAR Score 50</p><p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="open"><p class="flex" data-orientation="vertical" data-state="open" style="font-weight:bold;"></p><div aria-labelledby="radix-:rc:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="open" id="radix-:rd:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 632px;"><div class="prose px-4 pb-8"><p>If you’re an international student currently studying VCE in Australia, <a href="https://vtac.edu.au/">apply through VTAC</a>. If not, <a href="/link/10824d0d12ea4f57b870ef14178aad8b.aspx">find out how to apply directly to Federation University.</a></p><p>If you’re applying for a higher degree by research, make sure you <a href="/link/6efc37a41dd7457187d53a39c3475ba6.aspx">follow these instructions</a>.</p><p>Ready to fill out your application? You might need these codes:</p> <dl><dt><abbr title="Victorian Tertiary Admissions Centre">VTAC</abbr> application</dt><dd>Yes</dd><dt><abbr title="Victorian Tertiary Admissions Centre">VTAC</abbr> code</dt><dd>3701811903 - Berwick (on campus)<br/>3700511903 - Mt Helen (on campus)</dd><dt>Direct application</dt><dd>Yes</dd><dt>Federation University code</dt><dd>IT5</dd><dt><abbr title="Commonwealth Register of Institutions and Courses for Overseas Students">CRICOS</abbr> code</dt><dd>116468M</dd></dl></div></div></div></div></div></section>',
