UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><p>Graduates of this course will have the specialist knowledge required to understand and implement advanced software engineering techniques - design, implement and maintain IT systems using a well-informed software engineering approach and create high quality software in a systematic and efficient manner. Graduates may find employment in a wide range of industries including security and defence, education, aerospace, health, business and finance.</p></div><div><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Information Technology</p><h4>Course co-ordinator</h4><p>Azadeh Noori Hoshyar</p></div></div>',
    total_course_duration = '2 years full-time or part-time equivalent240 credit points = 2.0',
    offshore_tuition_fee = '41400',
    entry_requirements = '<section class="accordionContainerBlock py-12 lg:py-16 !pt-6 lg:!pt-12 !pb-4 lg:!pb-8" data-blk="AccordionContainerBlock" id="entry-requirement"><div class="container mx-auto"><p class="fs-5xl mb-8 font-semibold text-primary" style="font-weight:bold;"><p data-pm-slice="1 1 []">Entry requirements</p></p><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:r1b:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:r1c:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 252px;"><div class="prose px-4 pb-8"><h4>Academic entry requirements</h4><p>Successful completion of a recognised 3-year Australian bachelor degree or overseas equivalent</p><h4>English language requirements</h4><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent.</p></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="open"><p class="flex" data-orientation="vertical" data-state="open" style="font-weight:bold;"></p><div aria-labelledby="radix-:r1d:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="open" id="radix-:r1e:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 436px;"><div class="prose px-4 pb-8"><p>If you’re an international student currently studying VCE in Australia, <a href="https://vtac.edu.au/">apply through VTAC</a>. If not, <a href="/link/10824d0d12ea4f57b870ef14178aad8b.aspx">find out how to apply directly to Federation University.</a></p><p>If you’re applying for a higher degree by research, make sure you <a href="/link/6efc37a41dd7457187d53a39c3475ba6.aspx">follow these instructions</a>.</p><p>Ready to fill out your application? You might need these codes:</p> <dl><dt>Direct application</dt><dd>Yes</dd><dt>Federation University code</dt><dd>CG9</dd><dt><abbr title="Commonwealth Register of Institutions and Courses for Overseas Students">CRICOS</abbr> code</dt><dd>116467A</dd></dl></div></div></div></div></div></section>',
