UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><p>The purpose of this course is to provide participants with contemporary learning and teaching practices to complement the industry and/or research expertise they bring to the higher education setting. The intended learning outcomes of the GCETE are framed within the seven criteria of the Australian University Teaching Criteria and Standards Framework. The course content provides a foundation on which to develop quality pedagogies in a range of tertiary teaching environments supported by evidence research and scholarly practice. Learning activities and assessments support the creation of contemporary and relevant learning and teaching practices for use in your current and future courses. Examples include: course design assessment online and blended learning student engagement learning partnerships academic pathways and the scholarship of learning and teaching. Participants will be encouraged and supported to relate their learning directly to their workplace and areas of specialty</p></div><div><p>Institute of Education, Arts and Community - Delivered by Centre for Academic</p><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Education</p><h4>Course co-ordinator</h4><p>Anitra Goriss-Hunter</p></div></div>',
    total_course_duration = '2 years part-time',
    offshore_tuition_fee = '',
