UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><p>As a professional mining engineer you will oversee teams of engineering technologists and skilled trade staff to construct the designs you have created and work at a theoretical level to isolate analyse and define engineering outcomes. Mining engineers are in high demand in Australia and the Asia Pacific Region and work in all parts of the industry including feasibility studies mine design and managing production and sales. As a graduate you will be eligible to become a member of Engineers Australia and seek managerial roles with private consultants contracting companies or federal state and local government organisations. Upon successful completion you will be eligible for entry into the Graduate Diploma of Mining; Master of Engineering Technology (Mining) or the Master of Health (Workplace Health and Safety).<br/>This course provides you with real experience in your chosen profession, through our Co-operative Model. Please see the Work integrated learning section below for more details.</p></div><div><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Engineering</p><h4>Course co-ordinator</h4><p>Manoj Khandelwal</p></div></div>',
    total_course_duration = '2 years full-time or part-time equivalent240 credit points = 2.0',
    offshore_tuition_fee = '43500',
    entry_requirements = '<section class="accordionContainerBlock py-12 lg:py-16 !pt-6 lg:!pt-12 !pb-4 lg:!pb-8" data-blk="AccordionContainerBlock" id="entry-requirement"><div class="container mx-auto"><p class="fs-5xl mb-8 font-semibold text-primary" style="font-weight:bold;"><p data-pm-slice="1 1 []">Entry requirements</p></p><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:r1d:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:r1e:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 328px;"><div class="prose px-4 pb-8"><h4>Academic entry requirements</h4><p>Successful completion of an Australian bachelor’s degree or overseas equivalent.</p><p>Successful completion of a recognised 3- or 4-year Engineering Bachelor Degree in the relevant specialisation (major field) with credit average, awarded by an Australian University, or a recognised overseas equivalent.</p><h4>English language requirements</h4><p>Overall Academic IELTS band score of 6.0, with no band less than 6.0, or equivalent</p></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="open"><p class="flex" data-orientation="vertical" data-state="open" style="font-weight:bold;"></p><div aria-labelledby="radix-:r1f:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="op