UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><p>Biomedicine is an exciting area that plays a major role in helping people lead healthier lives. It''s an industry that is constantly evolving. You''ll learn about anatomy, pathophysiology, genetic sciences and can go on to work in areas like genome biology, genetic mapping, stem cell research and biological pharmaceuticals. Studies range from lifespan nutrition, to food microbiology, metabolism to applied biochemistry.</p><p>Graduates of this program will pursue a career in biomedical research, laboratory technology, medical sales, research and pharmaceuticals.</p><p>This degree is a pathway to postgraduate studies in medicine, physiotherapy, dentistry, pharmacy and other allied health programs, as well as veterinary science.</p><p>Please note: All online-enrolled students are required to attend a limited number of on-campus intensive labs and compulsory fieldtrips as part of their course.</p></div><div><div><p>This course is available via Online Learning, in combination with one to two weeks (depending on your program) of compulsory on-campus laboratory sessions. These lab sessions are held in semester one and semester two in each year of your course. You will also be required to complete examinations either on-campus, or at an approved remote exam location in your region, under supervision.</p><p> </p></div><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Science</p><h4>Course co-ordinator</h4><p>Berwick (on campus) - Indu Somasundara Panicker<br/>Gippsland (on campus) - Indu Somasundara Panicker<br/>Mt Helen (on campus) - Morgan Wallace<br/>Online - Morgan Wallace</p></div></div>',
    total_course_duration = '3 years full-time or part-time equivalent360 credit points = 3.0',
    offshore_tuition_fee = '',
    entry_requirements = '<section class="accordionContainerBlock py-12 lg:py-16 !pt-6 lg:!pt-12 !pb-4 lg:!pb-8" data-blk="AccordionContainerBlock" id="entry-requirement"><div class="container mx-auto"><p class="fs-5xl mb-8 font-semibold text-primary" style="font-weight:bold;"><p data-pm-slice="1 1 []">Entry requirements</p></p><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:ra:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:rb:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 448px;"><div class="prose px-4 pb-8"><h4>Academic entry requirements</h4><p>Successful completion of Australian Year 12 with one final year course in Mathematics (any) or one final year course of either chemistry, biology or physics or overseas equivalent.</p><h4>English language requirements</h4><p>Overall IELTS band score of 6.0, with no band less than 6.0 or equivalent</p><h4><abbr title="Australian Tertiary Admission Rank">ATAR</abbr></h4><p></p><p>Guaranteed ATAR: 60.00</p><p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="open"><p class="flex" data-orientation="vertical" data-state="open" style="font-weight:bold;"></p><div aria-labelledby="radix-:rc:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="open" id="radix-:rd:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 660px;"><div class="prose px-4 pb-8"><p>If you’re an international student currently studying VCE in Australia, <a href="https://vtac.edu.au/">apply through VTAC</a>. If not, <a href="/link/10824d0d12ea4f57b870ef14178aad8b.aspx">find out how to apply directly to Federation University.</a></p><p>If you’re applying for a higher degree by research, make sure you <a href="/link/6efc37a41dd7457187d53a39c3475ba6.aspx">follow these instructions</a>.</p><p>Ready to fill out your application? You might need these codes:</p> <dl><dt><abbr title="Victorian Tertiary Admissions Centre">VTAC</abbr> application</dt><dd>Yes</dd><dt><abbr title="Victorian Tertiary Admissions Centre">VTAC</abbr> code</dt><dd>3701837043 - Berwick (on campus)<br/>3700737043 - Gippsland (on campus)<br/>3700537043 - Mt Helen (on campus)</dd><dt>Direct application</dt><dd>Yes</dd><dt>Federation University code</dt><dd>SB5</dd><dt><abbr title="Commonwealth Register of Institutions and Courses for Overseas Students">CRICOS</abbr> code</dt><dd>062139A</dd></dl></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:re:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:rf:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 476px;"><div class="prose px-4 pb-8"><div><p>Credit will be considered if you have successfully completed higher education or TAFE studies. Advanced standing will be determined on an individual basis, depending on your eligibility for credit transfer, prior experience and qualifications.</p><p>If you are seeking alternative entry into the Bachelor of Biomedical Science you can consider applying for the following program:</p><p><a href="http://study.federation.edu.au/course/DFA0">Foundation Access Studies (FAST) Program</a> - designed to provide you with an alternative entry method into tertiary study.</p><p><strong>Further study options</strong></p><p>Further opportunities exist in Biomedical Science through an Honours research course comprising a focus on genetics/genomics, molecular and cellular biology, immunology, public health or health informatics.</p><p>The graduate medical course at Deakin University and graduate medical, physiotherapy, dentistry, veterinary science and other courses at other interstate universities provide opportunities for further study and specialisation for those graduates that satisfy the selection criteria upon completion of this degree.</p></div><p> </p></div></div></div></div></div></section>',
    apply_form = 'https://www.federation.edu.au/courses/dsb5-bachelor-of-biomedical-science/',
    created_at = '2026-06-26 21:07:07',
    updated_at = '2026-06-26 21:07:07'
WHERE cricos_course_code = '062139A';

UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><p>Our Bachelor of Education (Early Childhood Education) is a hands-on course that will get you into the classroom for a minimum of 80 days of supervised teaching placement so you can put into practice what you have learnt. You will develop the skills to teach in a variety of early education settings which may include kindergartens, pre-schools and long day care centres, including those in special needs settings.</p><p>A <a href="https://www.vic.gov.au/financial-support-study-and-work-early-childhood">range of scholarships</a> from the Victorian Department of Education and Training are available to help support your dream of a becoming an early childhood teacher, especially if you’re a regional student.</p><p>The Diploma of Early Childhood Education and Care is a pathway into the Bachelor of Education (Early Childhood Education). You may receive 1 year of credit (120 credit points) through this pathway.</p><p>We provide a number of pathways and options to ensure you can follow your dream of becoming a great teacher. Visit our <a href="https://federation.edu.au/become-a-teacher">Become a Teacher</a> website and use our interactive study tool to find your path to a rewarding career in education.<br/> </p></div><div><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Education</p><h4>Course co-ordinator</h4><p>Yuwen Ma<br/>Federation University Online - Kylie Routley</p></div></div>',
    total_course_duration = '3 years full-time or part-time equivalent360 credit points = 3.0',
    offshore_tuition_fee = '31800',
    entry_requirements = '<section class="accordionContainerBlock py-12 lg:py-16 !pt-6 lg:!pt-12 !pb-4 lg:!pb-8" data-blk="AccordionContainerBlock" id="entry-requirement"><div class="container mx-auto"><p class="fs-5xl mb-8 font-semibold text-primary" style="font-weight:bold;"><p data-pm-slice="1 1 []">Entry requirements</p></p><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:ra:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:rb:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 865px;"><div class="prose px-4 pb-8"><h4>Academic entry requirements</h4><div style="color: rgb(0, 0, 0); text-transform: none; text-indent: 0px; letter-spacing: normal; font-family: Calibri, Arial, Helvetica, sans-serif; font-size: 11pt; font-style: normal; font-weight: 400; word-spacing: 0px; white-space: normal; orphans: 2; widows: 2; background-color: rgb(255, 255, 255); -webkit-text-stroke-width: 0px; font-variant-ligatures: normal; font-variant-caps: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"><p>Successful completion of Australian Year 12 with final-year mathematics courses; or overseas equivalent.</p><p>Working with children check</p><p>Applicants will be required to hold a valid Working with Children (WWC) Check prior to undertaking professional placements.<br/>National Police Record Check: Some childcare centres may require students to hold a valid National Police Record Check for professional placements. Students will be notified if this is applicable.</p></div><h4>English language requirements</h4><p>IELTS score: Speaking 7.5, Listening 7.5, Reading 6.5 and Writing 6.5 </p><p>Successful completion of a relevant Australian diploma within the past two years with the proviso that students must prove they meet the English language requirement as determined by Australian Children''s Education and Care Quality Authority (ACECQA) to be eligible for registration.</p><h4>Extra requirements</h4><p>Equivalent English language test or successful completion of a relevant Australian diploma within the past two years with the proviso that students must prove they meet the English language requirement as determined by Australian Children''s Education and Care Quality Authority (ACECQA) to be eligible for registration.</p><h4><abbr title="Australian Tertiary Admission Rank">ATAR</abbr></h4><p></p><p align="LEFT">Lowest Adjusted ATAR 50.00<br/> </p><p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="open"><p class="flex" data-orientation="vertical" data-state="open" style="font-weight:bold;"></p><div aria-labelledby="radix-:rc:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="open" id="radix-:rd:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 632px;"><div class="prose px-4 pb-8"><p>If you’re an international student currently studying VCE in Australia, <a href="https://vtac.edu.au/">apply through VTAC</a>. If not, <a href="/link/10824d0d12ea4f57b870ef14178aad8b.aspx">find out how to apply directly to Federation University.</a></p><p>If you’re applying for a higher degree by research, make sure you <a href="/link/6efc37a41dd7457187d53a39c3475ba6.aspx">follow these instructions</a>.</p><p>Ready to fill out your application? You might need these codes:</p> <dl><dt><abbr title="Victorian Tertiary Admissions Centre">VTAC</abbr> application</dt><dd>Yes</dd><dt><abbr title="Victorian Tertiary Admissions Centre">VTAC</abbr> code</dt><dd>3701811763 - Berwick (on campus)<br/>3702311763 - Federation University Online</dd><dt>Direct application</dt><dd>Yes</dd><dt>Federation University code</dt><dd>TK5</dd><dt><abbr title="Commonwealth Register of Institutions and Courses for Overseas Students">CRICOS</abbr> code</dt><dd>107828M</dd></dl></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:re:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:rf:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 312px;"><div class="prose px-4 pb-8"><ul> <li>Defined TAFE pathway: A defined TAFE pathway program exists for this degree. Please note that additional essential requirements for admission may apply following completion of this pathway. CHC50121 or CHC50113 Diploma of Early Childhood Education and Care | credit for 120 credit points</li> <li>Students will get credit for: EDECE2022 Foundations of Language and Literacy, EDECE2023 The Early Childhood Professional, EDECE3022 Guiding Behaviours, EDBED1016 Learning and Teaching, EDECE1020 Planning, Supporting and Assessing, EDECE2019 Health and Safety in Early Childhood, EDECE2021 Wellbeing in Early Childhood Contexts, EDECE2001 Diversity: Children, Families and Communities.</li> <li>Other TAFE Studies: Apply for a relevant TAFE course, at any TAFE provider, and then apply to articulate into this program. You may receive credit for TAFE studies undertaken, which will be individually assessed upon request, after you enrol in your bachelor level course.</li></ul></div></div></div></div></div></section>',
    apply_form = 'https://www.federation.edu.au/courses/dtk5-bachelor-of-education-early-childhood-education/',
    created_at = '2026-06-26 21:07:07',
    updated_at = '2026-06-26 21:07:07'
WHERE cricos_course_code = '107828M';

UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><p>This program achieves a balance between general professional, specific practitioner, and research related skills.</p><p>This qualification comprises extensive, specialist study in both professional psychology and psychological research. With a strong research emphasis, you will plan, implement and report on a Research Project under supervision, in addition to undertaking a number of core courses (Psychological practice, Psychological research, Integrating research and practice and Psychological assessment). As this is an Honours program, it is aimed at students who wish to engage in research and professional practice in the field of psychology.</p></div><div><p> </p><p> </p><p><strong>Deferment of Admission </strong></p><p>Applicants are not permitted to defer admission into the program.</p><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Psychology</p><h4>Course co-ordinator</h4><p>Alex Poll</p></div></div>',
    total_course_duration = '1 year full-time or part-time equivalent120 credit points = 1.0',
    offshore_tuition_fee = '37600',
    entry_requirements = '<section class="accordionContainerBlock py-12 lg:py-16 !pt-6 lg:!pt-12 !pb-4 lg:!pb-8" data-blk="AccordionContainerBlock" id="entry-requirement"><div class="container mx-auto"><p class="fs-5xl mb-8 font-semibold text-primary" style="font-weight:bold;"><p data-pm-slice="1 1 []">Entry requirements</p></p><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:r1b:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:r1c:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 524px;"><div class="prose px-4 pb-8"><h4>Academic entry requirements</h4><p>Completion of a three-year sequence in psychology and qualified for an APAC accredited undergraduate degree (or overseas equivalent as determined by the Australian Psychological Society), or</p><p>Completion of a three-year undergraduate degree that is not APAC accredited and completion of a psychology sequence in a higher level, APAC accredited psychology degree (e.g., AQF 8 Graduate Diploma).</p><h4>English language requirements</h4><p>Overall Academic IELTS band score of 7.0, with no band less than 6.5, or equivalent.</p><h4><abbr title="Australian Tertiary Admission Rank">ATAR</abbr></h4><p></p><p>Entry requirements apply to this course.</p><p></p><p>Applicable to onshore international students applying for undergraduate/bachelor degree programs only.</p></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="open"><p class="flex" data-orientation="vertical" data-state="open" style="font-weight:bold;"></p><div aria-labelledby="radix-:r1d:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="open" id="radix-:r1e:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 436px;"><div class="prose px-4 pb-8"><p>If you’re an international student currently studying VCE in Australia, <a href="https://vtac.edu.au/">apply through VTAC</a>. If not, <a href="/link/10824d0d12ea4f57b870ef14178aad8b.aspx">find out how to apply directly to Federation University.</a></p><p>If you’re applying for a higher degree by research, make sure you <a href="/link/6efc37a41dd7457187d53a39c3475ba6.aspx">follow these instructions</a>.</p><p>Ready to fill out your application? You might need these codes:</p> <dl><dt>Direct application</dt><dd>Yes</dd><dt>Federation University code</dt><dd>HY8</dd><dt><abbr title="Commonwealth Register of Institutions and Courses for Overseas Students">CRICOS</abbr> code</dt><dd>088971K</dd></dl></div></div></div></div></div></section>',
    apply_form = 'https://www.federation.edu.au/courses/dhy8-bachelor-of-psychological-science-honours/',
    created_at = '2026-06-26 21:07:07',
    updated_at = '2026-06-26 21:07:07'
WHERE cricos_course_code = '088971K';

UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><div ng-bind-html="prg.program.outline"><div ng-bind-html="prg.program.outline"><p>The Bachelor of Science (Honours) is a fourth-year program for graduates of all Science, Information Technology and Mathematical Science undergraduate degrees. The program serves as a prelude to a higher degree in research or advanced professional practice in careers that entail complex research work.</p><p>The honours program consists of the core research project, as well as course work studies in research methodologies, communication, and the preparation of a literature review. A significant proportion (over one half) of the work in this program is the research project, which culminates in the submission of an Honours thesis. The aim of this course is to develop skills and experience in the type of work involved in postgraduate research studies.</p><p>The range of study areas in which we offer supervision include computing at a professional level for students with sufficient background in computing or information technology, and research based studies in all science disciplines, including Biomedical Science, Biotechnology, Environmental and Conservation Science, Food and Nutrition, Geoscience, Mathematical Sciences and Veterinary and Wildlife Science.</p><p>The research project allows you to pursue your area of interest in some depth whilst practising the investigative skills that are important in research. In particular, you will develop skills in finding the latest work published about your area of interest, and in assimilating and analysing this information. Course work also focusses on the preparation of a detailed research plan, designing and carrying out experimental research and writing up the results of your research. You will also learn how to communicate these findings to other people by giving seminars on your work and assembling your work in the form of a thesis.</p></div></div></div><div><p>Honours research projects</p><p>Honours research projects. Projects are available in all science disciplines. For more details, see the BSc Hons Handbook.</p><p><a href="https://www.federation.edu.au/siteassets/files/courses/Bachelor_of_Science_Honours_2026_handbook.pdf">Honours Program Handbook</a></p><p>Applications for Semester 1 2026 start, close on 17th November 2025.</p><p> </p><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Science</p><h4>Course co-ordinator</h4><p>Rob Bischof</p></div></div>',
    total_course_duration = '1 year full-time or part-time equivalent120 credit points = 1.0',
    offshore_tuition_fee = '38900',
    entry_requirements = '<section class="accordionContainerBlock py-12 lg:py-16 !pt-6 lg:!pt-12 !pb-4 lg:!pb-8" data-blk="AccordionContainerBlock" id="entry-requirement"><div class="container mx-auto"><p class="fs-5xl mb-8 font-semibold text-primary" style="font-weight:bold;"><p data-pm-slice="1 1 []">Entry requirements</p></p><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="closed"><p class="flex" data-orientation="vertical" data-state="closed" style="font-weight:bold;"></p><div aria-labelledby="radix-:r19:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="closed" id="radix-:r1a:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); transition-duration: 0s; animation-name: none; --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 280px;"><div class="prose px-4 pb-8"><h4>Academic entry requirements</h4><p>Applicants will have completed a bachelor''s degree in the relevant discipline with a high level of academic achievement, which is normally a distinction average or above in core discipline courses in the second and third years.</p><h4>English language requirements</h4><p>Overall IELTS band score of 6.0, with no band less than 6.0, or equivalent.</p></div></div></div></div><div data-orientation="vertical"><div class="border-b border-neutral-300" data-orientation="vertical" data-state="open"><p class="flex" data-orientation="vertical" data-state="open" style="font-weight:bold;"></p><div aria-labelledby="radix-:r1b:" class="!duration-500 overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down data-[state=closed]:h-0" data-orientation="vertical" data-state="open" id="radix-:r1c:" role="region" style="--radix-accordion-content-width: var(--radix-collapsible-content-width); --radix-collapsible-content-width: 1027.21875px; --radix-accordion-content-height: 436px;"><div class="prose px-4 pb-8"><p>If you’re an international student currently studying VCE in Australia, <a href="https://vtac.edu.au/">apply through VTAC</a>. If not, <a href="/link/10824d0d12ea4f57b870ef14178aad8b.aspx">find out how to apply directly to Federation University.</a></p><p>If you’re applying for a higher degree by research, make sure you <a href="/link/6efc37a41dd7457187d53a39c3475ba6.aspx">follow these instructions</a>.</p><p>Ready to fill out your application? You might need these codes:</p> <dl><dt>Direct application</dt><dd>Yes</dd><dt>Federation University code</dt><dd>SZ8</dd><dt><abbr title="Commonwealth Register of Institutions and Courses for Overseas Students">CRICOS</abbr> code</dt><dd>088661B</dd></dl></div></div></div></div></div></section>',
    apply_form = 'https://www.federation.edu.au/courses/dsz8-bachelor-of-science-honours/',
    created_at = '2026-06-26 21:07:07',
    updated_at = '2026-06-26 21:07:07'
WHERE cricos_course_code = '088661B';

UPDATE courses SET
    course_description = '<div class="wysiwyg prose line-clamp-14 overflow-hidden"><div><p>Study the biological principles underlying animal health, behaviour and diseases. This degree prepares you for careers in veterinary sciences (following further study), animal production and nutrition, and animal research.<br/> </p><p>Please note: All online-enrolled students are required to attend a limited number of on-campus intensive labs and compulsory fieldtrips as part of their course.</p></div><div><p style="font-weight:bold;">IT requirements</p><p>To do this course you’ll need a fast and reliable computer and access to high-speed internet. Expect to use about 5GB of data per month for every unit you’re doing. Find out more about the <a href="https://www.federation.edu.au/students/get-started/minimum-it-requirements/">minimum IT requirements</a> for studying with us.</p><h4>Got questions?</h4><p>Call us on 1800 333 864, start a live chat or <a href="https://www.federation.edu.au/contact/">submit an enquiry</a>.</p><h4>Student support</h4><p>The support we offer is second to none. Need academic help? No problem. Extra access or financial assistance? Let’s see what we can do. <a href="https://www.federation.edu.au/study/why-federation/support/">View our student services</a>.</p><h4>The fine print</h4><p>The commencement of all courses is subject to available funding and enrolment quotas.</p><p>Everything in this course overview is correct at the time of being published. However, the University reserves the right to alter any course, procedure or fee. Please check for changes before you apply or enrol.</p><p>Federation University uses Victorian and Commonwealth Government funding (for eligible students) to deliver training.</p><h4>School department</h4><p>Science</p><h4>Course co-ordinator</h4><p>David Piedrafita</p></div></div>',
